import Link from "next/link";
import { notFound } from "next/navigation";
import { EnquiryButtons } from "@/components/ServiceCards";
import serviceAreas from "@/data/serviceAreas.json";
import RoavioLayout from "@/layout/RoavioLayout";

async function getTour(params) {
  const { city, slug } = await params;
  const area = serviceAreas.find((item) => item.city === city);
  const tour = area?.services.find((item) => item.slug === slug);

  if (!tour) notFound();

  return { area, tour };
}

export async function generateMetadata({ params }) {
  const { area, tour } = await getTour(params);

  return {
    title: `${tour.name} in ${area.name} | Heritage Tour Guide India`,
    description: tour.summary,
  };
}

export default async function TourDetailsPage({ params }) {
  const { area, tour } = await getTour(params);
  const image = tour.image || area.image;

  return (
    <RoavioLayout>
      <section className="section-padding">
        <div className="container">
          <Link href={`/service-areas/${area.city}`}>
            View all {area.name} tours
          </Link>

          <h1 className="mt-3">{tour.name} in {area.name}</h1>
          <p>{tour.summary}</p>

          {image && (
            <img
              src={`/${image.replace(/^\/+/, "")}`}
              alt={tour.imageAlt || area.imageAlt || ""}
              className="img-fluid rounded my-4"
            />
          )}

          <p>{tour.description}</p>
          <p><strong>Duration</strong> · {tour.duration}</p>

          <h2 className="mt-4">Tour Highlights</h2>
          <ul className="mb-4">
            {tour.highlights.map((highlight) => (
              <li key={highlight}>{highlight}</li>
            ))}
          </ul>

          <EnquiryButtons name={`${tour.name} in ${area.name}`} />
        </div>
      </section>
    </RoavioLayout>
  );
}